/// A solid Font Awesome glyph at the given pixel size, the panes' 14 px.
#[component]
pub fn Fa(icon: Icon, #[prop(default = 14)] size: u8) -> impl IntoView {
    let (view_box, src) = icon.svg();
    let size = size.to_string();
    view! {
        <svg viewBox=view_box width=size.clone() height=size fill="currentColor" inner_html=src></svg>
    }
}
